namespace experiments;




using org.junit;
using org.junit;

public class ToArrayTest {

	long time(int n, IntConsumer run) {
		long start = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
		run.accept(n);
		return DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - start;
	}

	protected void runTest(Collection<string> col) {
		for (int i = 0; i < 10000000; i += 1000000) {
			Console.WriteLine("  Loops: " + i);

			Console.Write("    toArray(String[]::new): ");
			Console.WriteLine(time(i, n => {
				for (int j = 0; j < n; j++) {
					col.toArray(string[].new);
				}
			}) + "ms");

			Console.Write("    toArray(new String[0]): ");
			Console.WriteLine(time(i, n => {
				for (int j = 0; j < n; j++) {
					col.toArray(new string[0]);
				}
			}) + "ms");

			Console.Write("    toArray(new String[n]): ");
			Console.WriteLine(time(i, n => {
				for (int j = 0; j < n; j++) {
					col.toArray(new string[col.size()]);
				}
			}) + "ms");
		}
	}

	protected void fillCollection(Collection<string> col, int n) {
		for (int i = 0; i < n; i++) {
			col.add("String" + i);
		}
	}

	/* @Test */
	/* @Ignore */
	public void testHashSetToArrayPerformance() {
		Console.WriteLine("HashSet<String>(10):");
		Collection<string> col = new();
		fillCollection(col, 10);
		runTest(col);
	}

	/* @Test */
	/* @Ignore */
	public void testArrayListToArrayPerformance() {
		Console.WriteLine("ArrayList<String>(10):");
		Collection<string> col = new();
		fillCollection(col, 10);
		runTest(col);
	}
}
